const D: MvBook[] = [{"u":"Молитва на Благовіщення Пресвятої Богородиці","e":"Prayer for the Annunciation of the Most Holy Theotokos","secs":[{"h":"Тропар, глас 4","ps":["Днесь спасе́нія на́шего глави́зна, / і є́же от ві́ка та́їнства явле́ніє: / Син Бо́жий, Син Ді́ви бива́єть, / і Гавриї́л благода́ть благовіству́єть. / Ті́мже і ми с ним Богоро́диці возопії́м: / ра́дуйся, Благода́тная, // Госпо́дь с Тобо́ю."]},{"h":"Кондак, глас 8","ps":["Взбра́нной Воєво́ді побіди́тельная, / я́ко ізба́вльшеся от злих, / благода́рственная воспису́єм Ті раби́ Твої́, Богоро́дице, / но, я́ко іму́щая держа́ву непобіди́мую, / от вся́ких нас бід свободи́, да зове́м Ті: // ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Задостойник","ps":["Благовіству́й, земле́, ра́дость ве́лію, / хвалі́те, Небеса́, Бо́жию сла́ву.","Я́ко одушевле́нному Бо́жию киво́ту, / да ніка́коже ко́снеться рука́ скве́рних. / Устні́ же ві́рних, Богоро́дице, немо́лчно, / глас А́нгела воспіва́юще, / с ра́достію да вопію́ть: / Ра́дуйся, Благода́тная, / Госпо́дь с Тобо́ю."]},{"h":"Молитва","ps":["О, Пресвята́я, Богоізбра́нная Ді́во, Свята́го Уті́шителя Ду́ха Всенепоро́чная Неві́сто, Пребоже́ственнаго же Отця́ Небе́снаго Дщер Превожделе́нная, посреді́ те́рнія ми́ра сего́ Тім обрете́нная, я́ко крин пресві́тлий добро́тою ді́вства блиста́ющийся, да Си́ну Бо́жию Чи́стая Ма́тер Неіскусобра́чная бу́деши! Что у́бо воздади́м Тебі́ в пресві́тлий день сей Благові́щенія, во́ньже Арха́нгела Гавриї́ла красото́ю безмі́рнаго ді́вства Своєго́ удиви́ла єси́ і от того́ неізрече́нноє обра́дованіє восприя́ла єси́? Что принесе́м Тебі́ за вся утіше́нія Твоя́, ї́миже возвесели́ла єси́ в день сей весь мир ви́димий і неви́димий, найпа́че же па́дший дре́вле род челові́ч?","Днесь спасе́нія на́шего нача́ло і є́же от ві́ка та́їнства явле́ніє: ни́ні у́бо Сло́во Бо́жиє ти́хо сни́де с небе́с, я́ко ка́пля ка́плющая на зе́млю, і всели́ся в Твою́ Богоблагода́тную Ді́вственную утро́бу і бисть Плоть спасе́нія на́шего ра́ди. Сего́ ра́ди днесь А́нгели лику́ють на небесі́х і вся твар весели́ться і ра́дується, пра́зднующе нача́ло свобожде́нія своєго́ от рабо́ти істлі́нія в свобо́ду сла́ви чад Бо́жиїх. Ни́ні ра́дується же́нськоє єстество́, Є́ви ра́ди па́дшеє, та бо повину́вшися змі́ю печа́ль роди́ жена́м і неудержа́нно введе́ смерть. Ти же, Ді́во, разріши́ла єси́ от го́ркия рабо́ти весь род челові́ч і свобо́дою Христо́вою єстество́ же́нськоє почти́ла єси́, зане́ ді́вством чи́стим па́ки і́стинную жизнь ввела́ єси́, і сего́ ра́ди жени́, ді́вство держа́ще, врага́ я́ві побіжда́ти начина́ють. Ни́ні Ада́м лику́єть, ви́дів, я́ко в пресві́тлий день сей іспо́лнися на Тебі́ пе́рвоє ра́йськоє благові́стіє, я́ко сі́м'я Жени́ сотре́ть главу́ змі́я. С ни́мже ликовству́єть ни́ні весь род челові́ч, поне́же Тобо́ю, Пречи́стая, упраздни́ся днесь дре́внєє отвраще́ніє Бо́жиє к челові́ком, Бо́га бо па́ки привела́ єси́ к нам. Сего́ ра́ди зрим Тя ни́ні, я́коже дре́вле Іа́ков, я́ко Лі́ствицю Висо́кую, Є́юже сни́де Бог на зе́млю і я́ко Мост Пречу́ден, і́мже су́щих от землі́ па́ки возво́диши на не́бо. Что воздади́м Тебі́, Цари́це не́ба і землі́, за вся сія́, і́миже ра́дость несказа́нную подала́ єси́ па́дшим і заблу́ждшим лю́дем Твої́м? Вся на́ші же́ртви і приноше́нія нічто́же суть пред вели́чеством благодія́ній Твої́х. Єди́ноє то́чію уго́дно Тебі́: “се́рдце сокруше́нно і смире́нно”, єго́же і Син Твой і Госпо́дь наш “не унічижи́ть”. Сего́ ра́ди мо́лим Тя: іспо́лни нас от превосходя́щия висоти́ смире́нія Своєго́ єли́ка вмісти́ти возмо́жем, да принесе́м Ті во всесвяти́й день Благові́щенія Твоєго́ Твоя́ от Твої́х, во є́же во вся́цім ді́лі бла́зі не ми́слити висо́кая, но ви́ну в смире́нії ду́ха пребива́ти. Се́ю перве́йшею доброді́телію укра́шени, в пресві́тлий день сего́ пра́здника Твоєго́ в кро́тости і чистоті́ се́рдця со Арха́нгелом Гавриї́лом возопіє́м Тебі́: Ра́дуйся, Благода́тная, Ра́дуйся, Обра́дованная, Ра́дуйся, Преблагослове́нная, Госпо́дь с Тобо́ю і Тобо́ю с на́ми во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Арха́нгельський глас / вопіє́м Ті, Чи́стая: / Ра́дуйся, / Благода́тная, // Госпо́дь с Тобо́ю."]}],"notes":[]},{"u":"Молитва на Введення в храм Пресвятої Богородиці","e":"Prayer for the Entry of the Most Holy Theotokos into the Temple","secs":[{"h":"Тропар, глас 4","ps":["Днесь благоволе́нія Бо́жия предображе́ніє, / і челові́ков спасе́нія пропові́даніє, / в хра́мі Бо́жиї я́сно Ді́ва явля́ється, / і Христа́ всім предвозвіща́єть. / Той і ми велегла́сно возопії́м: // ра́дуйся, смотре́нія Зижди́телева ісполне́ніє."]},{"h":"Кондак, глас 4","ps":["Пречи́стий храм Спа́сов, / многоці́нний черто́г і Ді́ва, / свяще́нноє сокро́вище сла́ви Бо́жия, / днесь вво́диться в дом Госпо́день, благода́ть совводя́щи, / Я́же в Ду́сі Боже́ственном, / Ю́же воспіва́ють А́нгели Бо́жії: // Сія́ єсть селе́ніє Небе́сноє."]},{"h":"Задостойник","ps":["А́нгели, вхожде́ніє Пречи́стия зря́ще, удиви́шася, / ка́ко Ді́ва вни́де во свята́я святи́х.","Я́ко одушевле́нному Бо́жию киво́ту, / да ніка́коже ко́снеться рука́ скве́рних, / устні́ же ві́рних Богоро́дице немо́лчно, / глас А́нгела воспіва́юще, с ра́достію да вопію́ть: / і́стинно ви́шши всіх єси́, Ді́во Чи́стая."]},{"h":"Молитва","ps":["О, Пресвята́я Ді́во, Цари́ця Небесі́ і землі́, пре́жде вік ізбра́нная Неві́сто Бо́жія, в послі́дняя же времена́ прише́дшая в храм зако́ний на обруче́ніє Жениху́ Небе́сному! Ти оста́вила єси́ лю́ди Твоя́ і дом отця́ Твоєго́, во є́же принести́ Себі́ в же́ртву чи́стую і непоро́чную Бо́гові, і пе́рвая дала́ єси́ обі́т всегда́шняго ді́вства. Да́руй же нам соблюда́ти себі́ в цілому́дрії і чистоті́ і в стра́хі Бо́жиєм во вся дні живота́ на́шего, да бу́дем хра́ми Ду́ха Свята́го, найпа́че помози́ всім в подража́ніє Твоє́ во оби́теліх живу́щим і обручи́вшим себе́ на служе́ніє Бо́гові в чистоті́ ді́вства провожда́ти житіє́ своє́ і от ю́ности нести́ і́го Христо́во благо́є і ле́гкоє, свя́то храня́ще обі́ти своя́. Ти провела́ єси́, Всечи́стая, вся дні ю́ности Твоєя́ в хра́мі Госпо́днем вдали́ от собла́знов ми́ра сего́, в при́сном бо́дрствованії моли́твенном і во вся́ком воздержа́нії душе́вном і тіле́снім, помози́ і нам отража́ти вся іскуше́нія вра́жеськия от пло́ті, ми́ра і дия́вола находя́щих на ни от ю́ности на́шея, і побіжда́ти о́ния моли́твою і посто́м. Ти в хра́мі Госпо́днем со А́нгели пребива́ющи, укра́силася єси́ всі́ми доброді́тельми, найпа́че же смире́нієм, чистото́ю і любо́вію і досто́йно воспита́лася єси́, да гото́ва бу́деши вмісти́ти пло́тію Невмісти́моє Сло́во Бо́жиє. Сподо́би же і нам, одержи́мим го́рдостію, невоздержа́нієм і лі́ностію, облещи́ся во вся́коє соверше́нство духо́вноє, да угото́ваєть ки́йждо от нас с по́мощію Твоє́ю одія́ніє бра́чноє ду́ші своєя́ і єле́й доброде́ланія, да не на́зі і негото́ві яви́мся во срі́теніє Безсме́ртному Жениху́ на́шему і Си́ну Твоєму́, Христу́ Спаси́телю і Бо́гу на́шему, но да при́йметь ни с му́дрими ді́вами во оби́телі ра́йськия, іді́же со всі́ми святи́ми сподо́би нас ви́ну сла́вити і прославля́ти всесвято́є і́м'я Отця́ і Си́на і Свята́го Ду́ха і Твоє́ ми́лостивоє заступле́ніє всегда́, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / Богоізбра́нная Отрокови́це, / і чтим є́же в храм Госпо́день // вхожде́ніє Твоє́."]}],"notes":[]},{"u":"Молитва на Покрову Пресвятої Богородиці","e":"Prayer for the Protection of the Most Holy Theotokos","secs":[{"h":"Тропар, глас 4","ps":["Днесь благові́рнії лю́діє сві́тло пра́зднуєм / осіня́ємі Твої́м, Богома́ти, прише́ствієм, / і к Твоєму́ взира́юще Пречи́стому о́бразу, уми́льно глаго́лем: / покри́й нас честни́м Твої́м Покро́вом, / і ізба́ви нас от вся́каго зла, / моля́щи Си́на Твоєго́, Христа́ Бо́га на́шего, // спасти́ ду́ші на́ша."]},{"h":"Кондак, глас 3","ps":["Ді́ва днесь предстої́ть в це́ркві, / і с ли́ки святи́х неви́димо за ни мо́литься Бо́гу, / А́нгели со архієре́ї покланя́ються, / апо́столи же со проро́ки ликовству́ють: // нас бо ра́ди мо́лить Богоро́диця Преві́чнаго Бо́га."]},{"h":"Молитва перша","ps":["О, Пресвята́я Ді́во, Ма́ти Го́спода ви́шніх сил, Небесе́ і землі́ Цари́це, гра́да і страни́ на́шея Всемо́щная Засту́пнице! Прийми́ хвале́бно-благода́рственноє пі́ніє сіє́ от нас, недосто́йних раб Твої́х, і вознеси́ моли́тви на́ша ко Престо́лу Бо́га Си́на Твоєго́, да ми́лостив бу́деть непра́вдам на́шим, і проба́вить благода́ть Свою́ чту́щим всечестно́є і́м'я Твоє́ і с ві́рою і любо́вію покланя́ющимся чудотво́рному о́бразу Твоєму́. Ні́сми бо досто́йні от Него́ поми́ловані би́ти, а́ще не Ти уми́лостивиши Єго́ о нас, Влади́чице, я́ко вся Тебі́ от Него́ возмо́жна суть. Сего́ ра́ди к Тебі́ прибіга́єм, я́ко к несомні́нній і ско́рой Засту́пниці на́шей: усли́ши нас, моля́щихся Тебі́, осіни́ нас вседержа́вним покро́вом Твої́м, і іспроси́ у Бо́га Си́на Твоєго́: па́стирем на́шим ре́вность і бді́ніє о душа́х, градоправи́телем му́дрость і си́лу, судія́м пра́вду і нелицеприя́тіє, наста́вником ра́зум і смиренному́дріє, супру́гом любо́в і согла́сіє, ча́дом послуша́ніє, оби́димим терпі́ніє, оби́дящим страх Бо́жий, скорб'я́щим благоду́шіє, ра́дующимся воздержа́ніє, всім же нам дух ра́зума і благоче́стія, дух милосе́рдія і кро́тости, дух чистоти́ і пра́вди. Єй, Госпоже́ Пресвята́я, умилосе́рдися на немощни́я лю́ди Твоя́; разсі́янния собери́, заблу́ждшия на путь пра́вий наста́ви, ста́рость поддержи́, ю́ния уцілому́дри, младе́нці воспита́й, і при́зри на всіх нас призрі́нієм ми́лостиваго Твоєго́ заступле́нія, воздви́гни нас із глубини́ гріхо́вния і просвіти́ серде́чния о́чі на́ша ко зрі́нію спасе́нія, ми́лостива нам бу́ди зді і та́мо, в страні́ земна́го прише́льствія і на стра́шнім суді́ Си́на Твоєго́; преста́вльшіяся же во ві́рі і покая́нії от житія́ сего́ отці́ і бра́тію на́шу во ві́чній жи́зні со А́нгели і со всі́ми святи́ми жи́ти сотвори́. Ти бо єси́, Госпоже́, Сла́ва небе́сних і Упова́ніє земни́х, Ти по Бо́зі на́ша Наде́жда і Засту́пниця всіх, притека́ющих к Тебі́ с ві́рою. К Тебі́ у́бо мо́лимся, і Тебі́, я́ко Всемогу́щей Помо́щнице, са́мі себе́ і друг дру́га і весь живо́т наш предає́м, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["Цари́це моя́ Преблага́я, Наде́ждо моя́ Пресвята́я, прия́телище си́рим і стра́нним Засту́пнице, бі́дствующих по́моще і озлобля́ємих покро́ве, зри́ши мою́ напа́сть, зри́ши мою́ скорб: отвсю́ду іскуше́нієм одержи́м єсьм, а заступа́ющаго ність. Ти у́бо сама́ помози́ мі я́ко не́мощну, окорми́ м'я я́ко стра́нна, наста́ви я́ко заблу́ждша, уврачу́й і спаси́ я́ко безнаде́жна. Не і́мам бо іни́я по́мощі, ні іна́го предста́тельства, ні утіше́нія, то́кмо Тебі́, о Ма́ти всіх скорб'я́щих і обремене́нних! При́зри у́бо на м'я, грі́шнаго і во озлобле́нії су́щаго, і покри́й м'я пресвяти́м омофо́ром Твої́м, да ізба́влен бу́ду от зол, м'я обише́дших, і восхвалю́ ви́ну препі́тоє і́м'я Твоє́. Амі́нь."]},{"h":"Величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / і чтим Покро́в Твой святи́й: / Тя бо ви́ді святи́й Андре́й на возду́сі, / за ни Христу́ моля́щуюся."]},{"h":"Інше величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / Ма́ти Христа́, Бо́га на́шего, / і всесла́вний сла́вим Покро́в Твой."]},{"h":"Інше величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / Ма́ти Христа́, Бо́га на́шего, / І́же к Си́ну Свої́ ру́ці простира́ющи, і о ми́рі моля́щися, / і честни́м Свої́м омофо́ром защища́ющи / град і лю́ди от враго́в на́ших."]}],"notes":[]},{"u":"Молитва на Різдво Пресвятої Богородиці","e":"Prayer for the Nativity of the Most Holy Theotokos","secs":[{"h":"Тропар, глас 4","ps":["Рождество́ Твоє́, Богоро́дице Ді́во, / ра́дость возвісти́ всей вселе́нній: / із Тебе́ бо возсія́ Со́лнце пра́вди Христо́с Бог наш, / і, разруши́в кля́тву, даде́ благослове́ніє, // і, упраздни́в смерть, дарова́ нам живо́т ві́чний."]},{"h":"Кондак, глас 4","ps":["Іоаки́м і А́нна поноше́нія безча́дства, / і Ада́м і Є́ва от тлі сме́ртния свободи́стася, Пречи́стая, / во святі́м рождестві́ Твоє́м. / То пра́зднують і лю́діє Твої́, / вини́ прегріше́ній ізба́вльшеся, / внегда́ зва́ти Ті: // непло́ди ражда́єть Богоро́дицю і пита́тельницю Жи́зні на́шея."]},{"h":"Задостойник","ps":["Велича́й, душе́ моя́, / пресла́вноє рождество́ Бо́жия Ма́тере.","Чу́жде ма́терем ді́вство / і стра́нно ді́вам діторожде́ніє; / на Тебі́, Богоро́дице, / обоя́ устро́їшася. / Тім Тя, вся племена́ земна́я, // непреста́нно велича́єм."]},{"h":"Молитва","ps":["О, Пресвята́я і Богоізбра́нная Ді́во, Влади́чице на́ша Богоро́дице, Небесі́ і землі́ Цари́це, на ра́дость і утіше́ніє всему́ от безпло́дних і безча́дних роди́телей Бо́гом дарова́нная! Роди́вшися Бо́жиїм промишле́нієм, Ти разріши́ла єси́ непло́дствіє ро́ждшия Тя, і ни́ні непло́дноє се́рдце моє́ плодоно́стно сотвори́ предста́тельством Твої́м у Престо́ла Вседержи́телева, непло́дствовати же соді́лай м'я зли́ми ді́ли, гнили́ми словеси́ і нечи́стими помишле́ньми. О, Всеблаже́нная, да явлю́ся ча́до Бо́жиє, доброді́телей благопло́діє при́сно принося́щеє. Ти утоли́ла єси́ Пречи́стим Рождество́м Твої́м плач прама́тері на́шея Є́ви, і пра́ведния роди́телі Твоя́ ізба́вила єси́ поноше́нія безча́дства, і ни́ні утоли́ плач і воздиха́нія многоболі́зненния і грехолюбо́вния душі́ моєя́ і ізба́ви всіх нас поноше́нія злосмра́дних діл на́ших, страсте́й безче́стія і от вся́кого порабоще́нія вра́жеськаго. Найпа́че же да́руй нам, Пресвята́я Богоро́дице Ді́во, во всесві́тлий день Рождества́ Твоєго́ чи́стим се́рдцем разумі́ти і па́м'ятовати, с коли́кою ра́достію і благодаре́нієм непло́дная утро́ба святи́я пра́ведния А́нни ноша́ше Тя, да і ми не то́чію словеси́, но найпа́че ді́ли свої́ми ви́ну бу́дем со умиле́нієм серде́чнім прославля́ти Тя, вопію́ще: Сла́ва прише́ствію Твоєму́, Чи́стая. Сла́ва Рождеству́ Твоєму́. Сла́ва ді́вству Твоєму́, Ма́ти Безневі́стная. Ку́пно же с Тобо́ю сподо́би нас непреста́нно сла́вити і велича́ти Всесвяти́й Плод Твой, Сло́во воплоще́нно, во чре́ві Твоє́м неопа́льно носи́мо, Єму́же сла́ва подоба́єть, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м, і с Пресвяти́м і Благи́м і Животворя́щим Єго́ Ду́хом ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, і чтим святи́х Твої́х роди́телей, і всесла́вноє сла́вим Рождество́ Твоє́."]}],"notes":[]},{"u":"Молитва на Успіння Пресвятої Богородиці","e":"Prayer for the Dormition of the Most Holy Theotokos","secs":[{"h":"Тропар, глас 1","ps":["В рождестві́ ді́вство сохрани́ла єси́, / во успе́нії ми́ра не оста́вила єси́, Богоро́дице, / преста́вилася єси́ к животу́, Ма́ти су́щи Живота́, // і моли́твами Твої́ми ізбавля́єши от сме́рти ду́ші на́ша."]},{"h":"Кондак, глас 2","ps":["В моли́твах неусипа́ющую Богоро́дицю / і в предста́тельствах непрело́жноє упова́ніє / гроб і умерщвле́ніє не удержа́ста: / я́коже бо Живота́ Ма́тер / к животу́ преста́ви // во утро́бу Всели́вийся присноді́вственную."]},{"h":"Задостойник, глас 1","ps":["А́нгели, Успе́ніє Пречи́стия ви́дівше, удиви́шася, / ка́ко Ді́ва восхо́дить от землі́ на Не́бо.","Побіжда́ються єстества́ уста́ви / в Тебі́, Ді́во Чи́стая, / ді́вствуєть бо рождество́ і Живо́т предобруча́єть смерть; / по рождестві́ Ді́ва і по сме́рті жива́, / спаса́єши при́сно, Богоро́дице, наслі́діє Твоє́."]},{"h":"Молитва","ps":["О Пресвята́я Богоро́дице Ді́во, Влади́чице, ви́шшая А́нгел і Арха́нгел і всея́ тва́рі Честні́йшая, а́нгельськоє вели́коє удивле́ніє, проро́чеськая висо́кая про́повідь, апо́стольськая пресла́вная похвало́, святи́телей ізря́дноє украше́ніє, му́чеников крі́пкоє утвержде́ніє, і́ноков спаси́тельноє наставле́ніє, по́стников неізнемога́ющеє воздержа́ніє, ді́вствующих чистото́ і сла́во, ма́терей ти́хоє весе́ліє, младе́нцев му́дросте і наказа́ніє, вдови́ць і си́рих Корми́тельнице, наги́х оді́яніє, боля́щих здра́віє, плі́нников ізбавле́ніє, по мо́рю пла́вающих тишино́, обурева́ємих небу́рноє приста́нище, блужда́ющих нетру́дная Наста́внице, путеше́ствующих ле́гкоє прохожде́ніє, тружда́ющихся благо́є поко́їще, в біда́х су́щих ско́рая Засту́пнице, оби́димих Покро́ве і прибі́жище, ненаді́ющихся наді́яніє, тре́бующих Помо́щнице, печа́льних при́сноє утіше́ніє, ненави́димих любо́вноє смире́ніє, грі́шников спасе́ніє і к Бо́гу присвоє́ніє, правові́рних всіх тве́рдоє огражде́ніє, непобіди́моє поможе́ніє і заступле́ніє! Тобо́ю нам, Влади́чице, Неви́димий ви́дим бисть, і Тебі́ мольбу́ прино́сим, Госпоже́, грі́шнії раби́ Твої́: О Преми́лостивая і Пречу́дная Сві́та у́мнаго Цари́це, ро́ждшая Царя́ Христа́, Бо́га на́шего, Живода́вця всіх, от небе́сних сла́вимая і от земни́х хва́лимая, а́нгельський у́ме, світоза́рная звіздо́, святи́х Пресвяті́йшая, Влади́чице всіх тва́рей, Боголі́пная Діви́це, Нескве́рная Неві́сто, пала́то Ду́ха Пресвята́го, о́гненний Престо́ле Неви́димаго Царя́, небе́сний киво́те, носи́ло Сло́ва Бо́жия, огнеобра́зная колесни́це, поко́їще Жива́го Бо́га, неізрече́нноє составле́ніє пло́ті Христо́ви, гніздо́ Орла́ Небе́снаго, Го́рлице Богогла́сная, Голу́бице кро́ткая, ти́хая і незло́бивая, Ма́ти чадолюби́вая, ми́лостей бе́здно, разверга́ющая ту́чу гні́ва Бо́жия, неізміри́мая глубино́, неізрече́нная та́йно, несві́домоє чу́до, не рук отворе́нная Це́ркве Єди́наго Царя́ всіх вік, благоуха́нноє кади́ло, честна́я багряни́це, Боготка́нная порфи́ро, душе́вний раю́, живоно́снаго са́да о́трасле, цві́те прекра́сний, процві́тшій нам небе́сноє весе́ліє, гро́зде спасе́нія на́шего, ча́ше Царя́ Небе́снаго, в не́йже раствори́ся от Ду́ха Свята́го вино́ неісчерпа́ємия благода́ті, Хода́тайце зако́на, зача́ло і́стинния ві́ри Христо́ви непоколеби́мий сто́лпе, мечу́ я́рости Бо́жия на богопроти́вних, бісо́в устраше́ніє, во бра́ніх побіжде́ніє, христия́н всіх нело́жная Храни́тельнице і ми́ра всего́ ізві́стноє спасе́ніє! О Всеми́лостивая Госпоже́, Ді́во Влади́чице, Богоро́дице, усли́ши нас, моля́щихся Тебі́, і яви́ ми́лость Твою́ на люде́й Твої́х, моли́ Си́на Своєго́ ізба́витися нам от вся́каго зла і сохрани́ оби́тель на́шу і вся́ку оби́тель, і град, і страну́ ві́рних, і лю́ди, благоче́стно прибега́ющия і призива́ющия і́м'я Твоє́ свято́є, от вся́кия напа́сти, губи́тельства, гла́да, тру́са, пото́па, огня́, меча́, наше́ствія іноплеме́нников і междоусо́бния бра́ні, от вся́кия болі́зні і вся́каго обстоя́нія, да ні ра́нами, ні преще́нієм, ні мо́ром, ні вся́ким пра́ведним гні́вом Бо́жиїм ума́ляться раби́ Твої́. Но соблюда́й і спаса́й ми́лостію Своє́ю, Госпоже́, за ни моля́щися, і поле́зноє благорастворе́ніє возду́ха во вре́мені пло́днаго приноше́нія нам да́руй. Облегчи́, возста́ви і поми́луй, Преми́лостивая Влади́чице, Богоро́дице препі́тая, во вся́кой біді́ і нужді́ су́щия. Пом'яни́ раби́ Твоя́ і не пре́зри слез і воздиха́нія на́шего, і обнови́ нас бла́гостію Своєя́ ми́лості, да со благодаре́нієм утіша́ємся, обрі́тше Тя Помо́щницю. Умилосе́рдися, Госпоже́ Пречи́стая, на немощни́я лю́ди Твоя́, Наде́ждо на́ша. Разсі́янния собери́, заблу́дшия на путь пра́вий наста́ви, отпа́дшия от благочести́вия оте́чеськия ві́ри па́ки возврати́, ста́рость поддержи́, ю́ния вразуми́, младе́нці воспита́й і просла́ви сла́в'ящия Тя, ізря́дніє же — Це́рков Си́на Твоєго́ соблюди́ і сохрани́ в долготу́ дній. О Ми́лостивая і Преми́лостивая Цари́це Небесе́ і землі́, Богоро́дице Присноді́во! Хода́тайством Твої́м поми́луй страну́ на́шу і во́їнство єя́ і вся правосла́вния христия́ни, сохраня́ющи їх под кро́вом ми́лости Твоєя́, ри́зою Твоє́ю честно́ю защити́ і моли́ із Тебе́ воплощша́гося без сі́мене Христа́, Бо́га на́шего, да препоя́шеть ни сви́ше си́лою на вся ви́димия і неви́димия враги́ на́ша. Спаси́ же і поми́луй, Госпоже́, Вели́каго Господи́на і Отця́ на́шего (ім’я), Святе́йшего Патріарха Київського і всієї України, преосвяще́нния митрополи́ти, архієпи́скопи і єпи́скопи правосла́вния, ієре́ї же і дия́кони і весь при́чет церко́вний, і весь мона́шеський чин, і вся правові́рния лю́ди, поклоня́ющіяся і моля́щіяся пред честно́ю Твоє́ю іко́ною. При́зри на всіх нас призрі́нієм ми́лостивнаго Твоєго́ заступле́нія, воздви́гни нас із глубини́ гріхо́вния і просвіти́ о́чі серде́чния ко зрі́нію спасе́нія, ми́лостива нам бу́ди зді і на Стра́шнім Суді́ Си́на Твоєго́ о нас умоли́, преста́вльшіяся во благоче́стії от житія́ сего́ раби́ Твоя́ во ві́чній жи́зні со А́нгели і Арха́нгели і со всі́ми святи́ми причти́, да одесну́ю Си́на Твоєго́ Бо́га предста́нуть, і моли́твою Твоє́ю сподо́би вся правосла́вния христия́ни со Христо́м жи́ти і ра́дості а́нгельськия в Небе́сних селе́ніїх наслажда́тися. Ти бо єси́, Госпоже́, сла́ва Небе́сних і упова́ніє земни́х, Ти на́ша Наде́жда і Засту́пниця всіх притека́ющих к Тебі́ і Твоєя́ святи́я по́мощі прося́щих. Ти Моле́бниця на́ша те́плая к Си́ну Твоєму́ і Бо́гу на́шему. Твоя́ Ма́терняя моли́тва мно́го мо́жеть на умоле́ніє Влади́ки, і Твої́м предста́тельством ко Престо́лу благода́ті Пресвяти́х і Животворя́щих Єго́ Тайн приступа́ти дерза́єм, а́ще і недосто́йнії. Ті́мже всечестни́й о́браз Твой і руко́ю Твоє́ю держи́маго Вседержи́теля ви́дяще на іко́ні, ра́дуємся, грі́шнії, со умиле́нієм припа́дающе, і любо́вію сей цілу́єм, ча́юще, Госпоже́, Твої́ми святи́ми Богоприя́тними моли́твами дойти́ Небе́сния безконе́чния жи́зні і непости́дно ста́ти в день су́дний одесну́ю Си́на Твоєго́ і Бо́га на́шего, сла́в'яще Єго́ ку́пно со Безнача́льним Отце́м і Пресвяти́м, Благи́м, Животворя́щим і Єдиносу́щним Ду́хом, во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Велича́єм Тя, Пренепоро́чная Ма́ти Христа́ Бо́га на́шего, і всесла́вноє сла́вим Успе́ніє Твоє́."]}],"notes":[]},{"u":"Молитви до Пресвятої Богородиці на кожен день седмиці прп. ієросхимонаха Нила Сорського","e":"Prayers to the Most Holy Theotokos for Each Day of the Week by St Nilus of Sora","secs":[{"h":"Молитва в понеділок","ps":["От скве́рних уст прийми́ моле́ніє, о Нескве́рная, Чи́стая і Пречи́стая Ді́во Богоро́дице, і не возгнуша́йся мої́х слове́с, о Ра́досте моя́, но при́зри на м'я і поми́луй м'я, Ма́ти Зижди́теля моєго́. Во вре́м'я живота́ моєго́ не оста́ви мене́: ві́си бо, Влади́чице, я́ко на Тя всю мою́ наде́жду возлага́ю і все упова́ніє моє́ о Тебі́ єсть. Ті́мже і во вре́м'я сме́рти моєя́ предста́ни мі. Помо́щнице моя́, Ра́досте і Сла́досте моя́: не оста́ви мене́ тогда́, Наде́жде моя́, і не посрами́ мене́ тогда́. Вім бо, вім, Ді́во, я́ко мно́гим гріхо́м пови́нен єсьм, окая́нний, і трепе́щу, помишля́я час о́ний; но, Ра́досте моя́, яви́ мі тогда́ лице́ Твоє́, удиви́ на мні ми́лость Твою́, Хода́тайце спасе́нія моєго́; ізми́ м'я, Влади́чице, от лю́тости бісо́вськия і стра́шнаго і гро́знаго іспита́нія возду́шних духо́в, і зло́би їх ізба́ви, і всю тогдашнюю скорб і печа́ль на ра́дость преложи́ Твої́м присіще́нієм. І сподо́би безбі́дно прейти́ мі нача́ла і вла́сті тьми, і дости́гнути поклони́тися на Престо́лі Сла́ви сидящему Христу́ і Бо́гу на́шему, со Безнача́льним Єго́ Отце́м і Пресвяти́м Ду́хом, во ві́ки. Амі́нь."]},{"h":"Молитва у вівторок","ps":["О Пресвята́я Влади́чице моя́ Богоро́дице, А́нгелов і Арха́нгелов, Херуви́мов, Серафи́мов Пречестні́йшая і всіх святи́х Пресвяті́йшая, Ді́во Ма́ти Бо́жия! Спаси́ м'я, смире́ннаго і грі́шнаго раба́ Твоєго́: Ти бо ві́си, Всеми́лостивая Госпоже́, я́ко всю мою́ наде́жду по Бо́зі на Тя возлага́ю, і ність мі іна́го прибі́жища спаси́тельнаго, то́кмо Ти, Всеблага́я: Ти моя́ крі́пость, Влади́чице, Ти моя́ і си́ла. Ти моє́ ра́дованіє в ско́рбіх. Ти моє́ приста́нище во іскуше́ніях. Ти моє́ ісправле́ніє в паде́ніях. Ти і спасе́ніє моє́ всенаде́жноє, о Ма́ти Зижди́теля і Го́спода моєго́! Помози́ мі пла́вающему в пучи́ні житія́ сего́ люті́є обурева́ємому і бі́дствующему от потопле́нія гріхо́внаго. Даждь мі ру́ку по́мощі, Помо́щнице моя́, і ізба́ви м'я от тимі́нія глубини́, да не погря́зну в бе́здні отча́янія: бу́ря бо гріхо́в і страсте́й возста́ на м'я, і во́лни беззако́ній погружа́ють м'я. Но Ти, Милосе́рдная Ма́ти, в приста́нище безстра́стія наста́ви і спаси́ м'я, безнаде́жних Наде́ждо і Хода́тайце спасе́нія моєго́. Амі́нь."]},{"h":"Молитва в середу","ps":["Богоро́дице, Ти єси́ упова́ніє моє́, Ти мі єси́ Стіна́ і благонаде́жноє приста́нище і спаси́тельноє прибі́жище, утомляємому страсте́й нахожде́нієм. Спаси́ м'я от всіх враг мої́х, гоня́щих ду́шу мою́ і лов'я́щих ю разли́чними іскуше́нії: на путі́ бо сем, по нему́ же хожду́, мно́гія сі́ті скри́ша мі; мно́гія собла́зни, мно́гія неудо́бства, мно́гая пре́лести, мно́гія не́мощі, душе́вния і тіле́сния, уловля́ють м'я в паде́нія гріхо́вния. І уже́ аз, окая́нний, впадо́х в сі́ті вра́жия, і св'я́зан, і держи́м єсьм і́ми: і что сотворю́, отча́янний аз, недоумі́ю. А́ще бо восхощу́ пока́ятися, нечу́вствієм і ожесточе́нієм одержи́м єсьм; а́ще же пла́кати понужда́юся, не і́мам сокруше́нія серде́чнаго і слез ні поне́ єди́ния ка́плі. Уви́ окая́нства моєго́! Уви́ бі́дности моє́й! Уви́ лише́нія моєго́! Ко кому́ у́бо прибі́гну пови́нний аз? То́кмо к Тебі́, Благоутро́бная Ма́ти Го́спода і Спа́са на́шего, ненаде́жних Наде́ждо, Стіно́ і Покро́ве к Тебі́ притека́ющих! Не отри́ни у́бо мене́ блу́днаго, не возгнуша́йся мене́ скве́рнаго: Тебі́ бо єди́ну в жи́зні моє́й стяжа́х уті́ху, Ді́во Марі́є Богоро́дице, і к Тебі́ єди́ній во вся́кой ну́жді прибіга́ю со дерзнове́нієм: не оста́ви у́бо мене́ в жи́зні сей і во вре́м'я сме́рти моєя́, предста́ни в по́мощ. Помо́щнице моя́, да у́зрять Тя всі вразі́ мої́ і постидя́ться, Тобо́ю побіжде́ннії, Влади́чице, Хода́тайце спасе́нія моєго́. Амі́нь."]},{"h":"Молитва в четвер","ps":["Кто Тебі́ по достоя́нію ублажи́ти мо́жеть, Пресвята́я Ді́во, чії уста́ воспі́ти спосо́бни Твоє́ вели́чіє, всяк смисл превосходя́щеє? Вся пресла́вная о Тебі́ соді́янная та́їнства, Богоро́дице, ви́ше сми́сла і сло́ва суть; красоті́ Ді́вства Твоєго́ і пресві́тлой Чистоті́ Твоє́й удиви́шася Херуви́ми і ужасо́шася Серафи́ми; чудесе́ бо рождества́ Твоєго́ нетлі́ннаго ні челові́чеський, ні а́нгельський язи́к ізрещи́ не мо́жеть. От Тебе́ бо безлі́тний і Єдиноро́дний Син Бо́жий, Бог Сло́во, неізрече́нно вопло́щся, роди́ся і с челові́ки поживе́, і Тя, я́ко Ма́тер Свою́, зіло́ возвели́чи. Цари́цю Тя всея́ тва́рі показа́, нам же ізві́стноє спасе́нія приста́нище. Тім всі под кров Твой притека́ющії, разли́чними скорб'ями і болі́зньми одержи́мії, приє́млють от Тебе́ бога́тно утіше́ніє і ісціле́ніє і Тобо́ю от бід спаса́ються: Ти бо єси́ воі́стину Ма́ти всіх скорб'я́щих і обремене́нних, печа́льних Ра́дость, больни́х Ціли́тельниця, ю́ним храни́тельниця, ста́рости жезл, пра́ведних похвала́, грі́шним спасе́нія наде́жда і к покая́нію Путеводи́тельниця: всім бо всегда́ предста́тельством Твої́м помога́єши і всіх заступа́єши, Всеблага́я, прибіга́ющих к Тебі́ с ві́рою і любо́вію. Ти і мні помози́, отча́янному дія́ній мої́х ра́ди. Засту́пнице усе́рдная ро́да христия́нськаго; заступи́ м'я, да не до конця́ поги́бну во грісі́х, і́бо не і́мам іна́го прибі́жища і покро́ва, ра́зві Тебе́, Влади́чице Ма́ти Живота́; не оста́ви у́бо мене́ і не пре́зри м'я, но і́ми же Сама́ ві́си судьба́ми спаси́ м'я, я́ко Благослове́нна єси́ во ві́ки віко́в. Амі́нь."]},{"h":"Молитва в п’ятницю","ps":["Тобі віддаю під захист життя моє і по Богові всю надію спасіння мого на Тебе покладаю, Владичице Діво Богородице. Благаю Тебе, раб Твій, не знехтуй мене, що маю багато гріхів, але поглянь на скорботу мою з цього приводу й на розгубленість та подай мені полегшення й втіху, щоб я не загинув до кінця. Простягни десницю Твою, Чистая, вирви мене з багна справ моїх і настав на чисте пасовисько заповідей Христа, Царя й Бога мого, щоб я творив їх повсякчас, Тобою зміцнюваний. Від гріхів моїх лютих визволи мене, Владичице, і покаяння спасительне випроси мені в Твого Сина і Бога Матерніми молитвами Твоїми. Світло невимовне просвітила, освіти мою душевну темряву, що постала від гріхів. Радосте моя, визволи мене від невидимих ворогів, що обступили мене: бо гріхи мої численні й тяжкі, вороги мої вельми люті, смерть близько, совість моя викриває мене, геєна вогненна лякає, червак невсипущий, скрегіт зубів, тартару темрява кромішня в тремтіння мене вводять, бо чекають на мене, щоб прийняти за злі діла мої. Горе мені! Що вчиню тоді і до кого вдамся, щоб душа моя була спасена! До Тебе єдиної, солодка Маріє Богородице, що підсолоджуєш тим, хто на Тебе уповає, гіркоту смерті й визволяєш тих, хто взиває до Тебе, від лютої геєни. Ти й мені допоможи, Всеблага, бо не матиму тоді іншої помочі, окрім Тебе, Всеспівана. Спаси мене від жахів смертної години і від лютості тоді бісівської, спаси мене від влади духів злоби на повітряних митарствах по смерті; з’яви, благаю Тебе, з’яви мені тоді Пресвітле лице Твоє, Владичице, і не залиш мене безпомічним. О Милосердна Мати! Схились на милість до мене, позбавленого милості через діла мої, і випроси в Того, Кого Ти народила в плоті, Христа, Спасителя й Бога нашого, що задля нас на Хресті пречисту Кров Свою пролив, щоб і я став учасником заслуг Його хресних перед Отцем Його Богом, і заради них отримав прощення гріхів і вічне спасіння, і прославив невимовне милосердя Твоє, Богородице, і Твоє милостиве заступництво на безконечні віки. Амінь."]},{"h":"Молитва в суботу","ps":["Ра́дуйся, Ді́во Богоро́дице, приста́нище і предста́тельство убо́гія душі́ моєя́, Наде́жда Сла́дкая спасе́нія моєго́! Ра́дуйся, ра́дость от А́нгела приє́мшая в благовещенії імі́ющаго воплоти́тися от Тебе́ Бо́га Сло́ва! Ра́дуйся, всіх Зижди́теля в Твої́х ложесна́х носи́вшая! Ра́дуйся, Бо́га пло́тію ро́ждшая, ми́ру Спаси́теля! Ра́дуйся, в рождестві́ Ді́вство нетлі́нно сохранившая! Ра́дуйся, от волхво́в да́ри приє́мшая і поклоне́ніє їх от Тебе́ Ро́ждшемуся ви́дівшая, і па́стирей пресла́вная о Нем словеса́ сли́шавшая і в се́рдці Твоє́м слага́вшая! Ра́дуйся, О́трока Ісу́са, Си́на Твоєго́ і Бо́га, во хра́мі, среди́ законоучи́телей, обрі́тшая ра́достно! Ра́дуйся, болі́зні лю́тия во страда́нії крестном, расп'я́тії і сме́рті Си́на Твоєго́, Пресла́дкаго Ісу́са, іспитавшая, Воскресе́нієм же Єго́ тридне́вним обра́дованная сві́тло! Ра́дуйся, Вознесе́ніє Си́на Твоєго́ і Бо́га со ученики́ Єго́ во сла́ві небе́сній ви́дівшая! Ра́дуйся, от Него́ ниспосланнаго Ду́ха Свята́го, в го́рниці Сіо́нстій во ви́ді о́гненних язи́ков нисшедшаго, со ученики́ Госпо́дні приє́мшая! Ра́дуйся, на землі́ а́нгельськи пожи́вшая! Ра́дуйся, чистото́ю і святи́нею вся а́нгельськия чи́ни і всіх святи́х ли́ки превосходя́щая! Ра́дуйся, возвели́ченная сла́вою, прише́ствієм к Тебі́ Си́на Твоєго́ і Бо́га! Ра́дуйся, Того́ святи́м рука́м ду́шу Твою́ ра́достно преда́вшая! Ра́дуйся, сла́вно превознесе́нная Твої́м на небеса́ с ті́лом восшествієм! Ра́дуйся, по преставле́нії Твоє́м Боговидцям Апо́столом в тре́тій день яви́вшаяся! Ра́дуйся, на небесі́х от Отця́ і Си́на і Ду́ха Свята́го діядемою Ві́чнаго Ца́рствія увінча́нная! Ра́дуйся, от всіх небе́сних сил Приснопіва́ємая! Ра́дуйся, близ престо́ла Пресвяти́я Тро́йці, на Престо́лі сла́ви возсідя́щая! Ра́дуйся, Бо́га с челові́ки примире́нія вино́внице! Ра́дуйся, небе́сними і земни́ми госпо́дствующая Цари́це! Ра́дуйся, я́ко нічто́же невозмо́жно єсть Твоєму́ хода́тайству! Ра́дуйся, я́ко всі ві́рно, к Тебі́ притекающиє спаса́ються! Ра́дуйся, я́ко Тобо́ю скорб'я́щим утіше́ніє, боля́щим ісціле́ніє, бедствующим благовре́менную по́мощ получа́ють! Молю́ у́бо Тя, обра́дованная Влади́чице, потреби́ і во мні печа́ль гріхо́вную і даждь мі ра́дость спасе́нія, даждь мі сле́зи уті́шительния, умиле́ніє всегда́шнєє, покая́ніє і́стинноє і ісправле́ніє соверше́нноє. Не возгнуша́йся мене́, Влади́чице, но прийми́ ми́лостиво сі́ї гла́си ра́достния, мно́ю, убо́гим, Тебі́ приноси́мия, і предста́ни мі в по́мощ во вре́м'я безпомо́щія моєго́, в час стра́шний о́ний, єгда́ разлучи́тися і́мать душа́ моя́ от окая́ннаго моєго́ ті́ла; тогда́, молю́, предста́ни мі в по́мощ і ізба́ви м'я, пови́ннаго во грісі́х, наказа́нія за них ві́чнаго, да не явлю́ся ра́дованіє бісо́м і пи́ща геєне о́гненній. Єй, Влади́чице моя́, не попусти́ узрі́ти душі́ моє́й стра́шнаго і гро́знаго преще́нія і істяза́нія де́монськаго, грі́шником угото́ваннаго, но предвари́ і спаси́ м'я, раба́ Твоєго́, в час о́ний ужа́сний, да сла́влю Тя во ві́ки, єди́на наде́жде моя́ і Хода́тайце спасе́нія моєго́. Амі́нь."]},{"h":"Молитва в неділю","ps":["О Всеми́лостивая Ді́во Богоро́дице, Ма́ти щедро́т і человіколю́бія, прелюбе́зная Наде́жде і упова́ніє моє́! О Ма́ти Пресладкого, Превожделі́ннаго і вся́ку люби́ превосходя́щаго Спаси́теля Ісу́са Христа́, Человіколю́бця і Бо́га моєго́. Сві́те помраче́нния душі́ моєя́! К Тебі́ аз, многогрі́шний і безнадежний, припа́даю, Тебі́ молю́ся, Істо́чниче милосе́рдія, Ді́во Марі́є, я́же бе́здну милосе́рдія і пучи́ну щедро́т і человіколю́бія ро́ждшая; поми́луй м'я, вопію́ Ті болі́зненно, поми́луй м'я всего́ уя́звленнаго, в лю́тия разбо́йники впа́дшаго і от оде́жди, в ню́же облече́ м'я Оте́ць, уви́ мні, обнаженного. Тім і лежу́ наг от вся́каго благотворе́нія, возсмерді́ша і согни́ша ра́ни моя́ от лиця́ безу́мія моєго́. Влади́чице моя́ Богоро́дице, молю́ Тя смире́нно, воззри́ на м'я ми́лостивим Твої́м о́ком і не возгнуша́йся мене́ всего́ помраче́ннаго, всего́ оскверне́ннаго, всего́ в ти́ні сласте́й і страсте́й погруже́ннаго, лю́ті па́дшаго і возста́ти не могу́щаго. Умилосе́рдися у́бо на м'я і даждь мі ру́ку по́мощі, воздви́гни м'я із глубини́ гріхо́вния, о Ра́досте моя́! Ізба́ви м'я от обише́дших м'я; просвіти́ лице́ Твоє́ на раба́ Твоєго́, спаси́ погиба́ющаго, очи́сти оскверне́ннаго, возста́ви па́дшаго лю́ті: мо́жеши бо вся, я́ко су́щи Ма́ти Бо́га Всемогу́щаго. Ізле́й на м'я єле́й милосе́рдія Твоєго́ і вино́ умиле́нія точи́ти мі пода́ждь: Тебі́ бо воі́стину єди́ну наде́жду стяжа́х в животі́ моє́м; не отри́ни у́бо мене́ к Тебі́ притека́ющаго, но виждь скорб мою́, Ді́во, і душі́ жела́ніє, і сіє́ прими́ і спаси́ м'я, Хода́тайця спасе́нія моєго́. Амі́нь."]}],"notes":[]},{"u":"Хвалебна пісня до Пресвятої Богородиці, подібна до твору Амвросія Медіоланського","e":"Hymn of Praise to the Most Holy Theotokos, after St Ambrose of Milan","secs":[{"ps":["Тебе́, Ді́ва, хва́лим, / Тебе́, Пречи́стая, іспові́дуєм, / Тебе́ по всей вселенной","сла́вить Свята́я Це́рков. / Тебі́, Дщер Отця́ Небесного, велича́єм, / Тебе́, Ма́тер Си́на Бо́жия, ублажа́єм, /","Тебі́, Неві́сто Свята́го Ду́ха, превозно́сим. / Ти от всіх родо́в Бо́гом ізбра́нная, / і к воплоще́нію Си́на Бо́жия преуготованная. /","Ти єди́на безсі́менно от Ду́ха Свя́та во чре́ві заче́ншая / і па́че єстества́ Іскупи́теля ми́ра ро́ждшая. /","Ти єди́на в жена́х благослове́нная: / рождество́ с ді́вством неізрече́нно сочета́вшая і приснодевством єди́на запечетленная. /","Ти во успе́нії ди́вно возвели́ченная: / із гро́ба я́ко Ма́тер Живота́ воста́вшая і на небеса́ с пречи́стою пло́тію вознесе́нная. /","Ти одесну́ю Си́на і Бо́га предстої́ши і о всем ми́рі мо́лишися, / Тебі́ славосло́вить А́нгельський собо́р, / Тебі́ ублажа́єть челові́чеський род. /","Іспо́лнени небеса́ і земля́, о Всепі́тая, сла́ви Твоєя́. / Ти Цари́ця не́ба і землі́, / Ти жили́ще Свята́го Ду́ха, не́бо і храм Божества́, /","Ти пала́та і престо́л Царе́в, / Ти царе́й держа́вная храни́тельниця, / Ти ді́вственних сла́ва і похвала́, / Ти па́стирем весе́ліє і ра́дованіє, /","Ти мона́шествующих усе́рдная путеводи́тельнице, / Ти христия́ном ми́лостивая помо́щниця. / Ти Ма́ти скорб'я́щих і озло́бленних. /","Ти о всіх грі́шних і заблудших промишля́єши. / Тебе́ у́бо про́сим, помози́ рабо́м Твої́м, / їх же Син Твой Честно́ю Кро́вію іскупи́л єси́. /","Удостой нас, Мати Всеспівана, у вічній славі з Тобою царювати, Тебе, нашу Заступницю й Покровительку, з Ангелами й усіма святими вічно хвалити й славити.","Бу́ди ми́лость Твоя́, Влади́чице, на нас, / я́коже упова́хом на Тя, / на Тя, о Всепі́тая, упова́хом / да не постиди́мся во ві́ки.","Амі́нь."]}],"notes":[]},{"u":"Пісня Пресвятій Богородиці","e":"Hymn to the Most Holy Theotokos","secs":[{"ps":["Богоро́дице Ді́во, ра́дуйся, Благода́тная Марі́є, Госпо́дь с Тобо́ю; благослове́нна Ти в жена́х і благослове́н плод чре́ва Твоєго́, я́ко Спа́са родила́ єси́ душ на́ших."]}],"notes":[]},{"u":"Молитва подячна до Пресвятої Богородиці","e":"Prayer of Thanksgiving to the Most Holy Theotokos","secs":[{"ps":["Что Ті принесе́м, іли́ что Ті воздади́м, о преми́лостивая Госпоже́ Влади́чице, Засту́пнице ро́да христия́нськаго, за вся Твоя́ неісче́тная благодія́нія, я́же при́сно явля́єши всім призива́ющим і́м'я Твоє́ і Твоєя́ по́мощі просящим. Кто бо притека́яй к Тебі́ посра́млен і неусли́шан от Тебе́ отхо́дить, о премилосе́рдая Ма́ти; ві́ми, Пречи́стая, я́ко за мно́жество гріхо́в і беззако́ній на́ших, ні́сми досто́йні ніже́ і́м'я Твоє́ пресла́дкоє нарещи́, не то́чію піснопі́нія от оскверне́нних усте́н Тебі́ приноси́ти, і удо́біє єсть нам молча́ніє люби́ти. Но да не яви́мся непам'ятливи і неблагода́рни пред Тобо́ю, дерза́єм приноси́ти Тебі́ сіє́ колінопреклоне́нноє славосло́віє. Ти же, премилосе́рдая Ма́ти, не возгнуша́йся прия́ти є, я́ко от ізби́тка лю́б'ящих Тя серде́ць возноси́моє. Сама́ Ти, Влади́чице, благода́тією твоє́ю косни́ся серде́ць на́ших, да я́ко воск раста́явша пролію́ться пред Тобо́ю в сле́зних благодаре́ніїх і славосло́віїх. Благодари́м Тя, Всепі́тая: не таї́м благодія́ній Твої́х, но велегла́сно возвіща́єм, да всі сли́шащії притека́ють к Тебі́, єди́ній непости́дній Засту́пнице ро́да христия́нськаго, і да немо́лчно славосло́в'ять Тя, Всепі́тую, во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитви прп. Єфрема Сиріна до Пресвятої Богородиці на кожну годину","e":"Prayers of St Ephrem the Syrian to the Most Holy Theotokos for Each Hour","secs":[{"h":"Година перша","ps":["Пресвята Владичице Богородице, єдина чиста душею і тілом, єдина, що перевершила цнотливість і дівство, єдина, що стала обителлю всієї благодаті Всесвятого Духа! Не відкинь мене недостойного, нечистого, що осквернив душу й тіло розпусним життям своїм; очисти розум мій від потягу до пристрастей; обрати до непорочних прагнень блукаючі й сліпі помисли мої; будь керівницею почуттів моїх; визволи мене від владарюючої наді мною лихої й ганебної схильності до забобонів і пристрастей; ослаб гнітючий мене гріх і окаянному, затьмареному розумові моєму даруй бадьорість і розсудливість, щоб, визволившись від гріховної пітьми, удостоїтися хвалебними піснями прославляти Тебе, істинну Матір Істинного Світла, Христа Бога нашого, бо Тебе єдину з Ним і про Нього благословляють видимі й невидимі створіння нині і повсякчас, і на віки віків. Амінь."]},{"h":"Година друга","ps":["Благаю Тебе, Родителько Невечірнього Світла: послухай, що розповім Тобі. У багно загрузаю, окаянний; землю безліччю гріхів осквернив… І здається мені: стогне земля і зі зідханням свідчить проти мене неупередженому Судді, закликаючи за свідків і сонце, і небо зі зорями… Буря дум моїх занурює мене вже в розпач. З трепетом підступає душа моя в очікуванні вироку. Вся надія моя на Тебе, Богородице!","Сорому сповнене лице служителя Твого, хоча й невпинно благаєш Ти Народженого Тобою, щоб дав Він від щедрот Своїх і мені, недостойному. Розв’яжи нерозв’язні узи мої, — осквернене убіли слізьми покаяння. Ти, що народила Життя моє, воскреси мене, умертвленого безтурботністю; і відчуженого від ангелів підніми до них, Богородице!","Страшне чудо, воістину страшне! Як Господь стерпів гріхи мої! Як живим ще не зіпхнув Він мене на дно пекла! Як не послав згори невидимої зброї, щоб поразити мене!..","Владичице, Ти молитвами Своїми дарувала мені життя, очікуючи мого покаяння, яке Сама дай мені, рабу Твоєму, бо Ти — мій притулок і огорожа.","Осяй мене світлом Божественного лика Твого, щоб уночі возгласити Тобі пісню. Дай мені, Владичице, скруху серцеву, ридання й сльози; дай досконале залишення гріхів, як Жона, що мала в утробі втіленого Бога. Нехай уночі побачу Тебе, Пречиста, розумним поглядом, і зрадію.","О, твердине моя, надіє моя, солодке світло рабу Твоєму! Прийми молитву з нечистих уст моїх! Нехай буде ніч ця днем спасіння рабу Твоєму, Богоневісто! Знаю, чого б не захотіла Ти, усе зможеш перед лицем Народженого Тобою, Якому належить усяка слава, честь і поклоніння на віки віків. Амінь."]},{"h":"Година третя","ps":["Діво Владичице, Богородице, що носила в утробі Христа Спасителя і Бога нашого, на Тебе покладаю всю надію, на Тебе уповаю, бо Ти — вища за безплотні сили! Охороняй мене, Пречиста, Своєю Божественною благодаттю; керуй життям моїм згідно зі святою волею Сина Твого і Бога нашого.","Даруй мені відпущення гріхів і будь мені прибіжищем, покровом, захистом і путівницею в життя вічне.","У страшну годину смертну не залиш мене, Владичице, але поспіши на допомогу мені і вирви мене з рук бісів-мучителів.","Ти єдина, Владичице Богородице, піднесена над усією землею; ми ж, Богоневісто, благословляємо Тебе з вірою, величаємо Тебе з любов’ю, поклоняємося Тобі зі страхом, бо Ти — честь честей, висота висот.","Владичице, Богом дарована мені розрадо, Божественне зрошення внутрішньої спеки моєї, знову пробитий струмене в висохлому джерелі сліз моїх, променистий світильнику затьмареної душі моєї, багатство в убогості, сило в немочах, зцілення невиліковних ран, припинення ридань, знищення кайданів!","Вислухай молитовні зідхання мої, змилуйся над моїм плачем, і, розчулившись слізьми моїми, схились на прохання моє, і яви мені милосердя, як Мати Чоловіколюбного Бога!","Виконай невгамовне бажання моє, визволи мене від мучительної пристрасті, що вбиває душу мою, і приєднай мене до Себе в землі живих, на лоні праведних.","Благаю Тебе, спільна всіх радосте, спільне всіх заступництво, удостой мене звеселитися невимовною радістю Народженого Тобою Царя і Бога, в невимовному Його чертозі, у безконечній солодощі, у вічному Царстві Його.","Владичице моя, прибіжище моє, життя, зброє, похвало, надіє і сило! Удостой мене насолодитися незбагненними дарами Сина Твого!","Цього прошу в Тебе, тому що Ти, як Мати Всевишнього, маєш відповідну бажанню Твоєму силу. Тому сподіваюся, що отримаю очікуване від Тебе, Богоневісто, що народила надію всіх, Господа нашого Ісуса Христа, Якому належить усяка слава, честь і поклоніння з Безначальним Його Отцем, і Благим, і Животворящим Його Духом, нині і повсякчас, і на віки віків. Амінь."]},{"h":"Година четверта","ps":["Знаю, Діво Владичице, Богородице, що недостойний я дивитися на Твій образ, бо тіло й душа Твоя чисті, і Ти, по справедливості, повинна гидувати мною. Але оскільки Народжений Тобою Бог для того став Людиною, щоб закликати грішних до покаяння, то прийми мою сповідь у безлічі тяжких прогрішень і випроси в Сина Твого і Бога, щоб явив Він милість убогій душі моїй.","Велика безліч беззаконь перешкоджає мені звести до Нього погляд і самому просити в Нього прощення. Насолодившись багатьма дарами від Бога, що створив мене, усе забув я, невдячний! Бідний я на доброчесності, а багатий на пристрасті; сповнений сорому й засуджений Богом.","Оплакують мене ангели, сміються наді мною демони, викриває мене совість, соромлять мої власні вчинки; до смерті я мертвець, до суду засуджений самим собою, до безконечної муки мучуся розпачем.","Тому й вдаюся до скорої допомоги Твоєї, Владичице Богородице! Зійди до смирення мого, Пречиста; змилуйся над немічністю моєю, Непорочна! Велику Ти маєш сміливість перед Народженим Тобою: такої не має ніхто інший.","Ти все можеш, як Мати Божа, — і немає для Тебе нічого неможливого, якщо тільки Ти захочеш.","Не гордуй лише слізьми й риданнями моїми, не відкинь скорботи серця мого, не залиш марною надію мою на Тебе!","Молитвами Твоїми схили милосердя Сина і Бога Твого і удостой мене, нещасного й недостойного раба Твого, відновити первісну душевну красу, скинути з себе потворність пристрастей, звільнитися від гріха, схилитися перед правдою, викорінити розпусту й зодягнутися у святиню безпристрасності, померти для світу й ожити для доброчесності.","Будь мені в дорозі супутницею і плаваючого супроводжуй мене, зміцнюй мене, коли пильную, оберігай, коли сплю, втішай, коли плачу, підбадьорюй, коли занепадаю духом, визволяй ображеного, звільняй обмовленого, підіймай немічного; перемагай воюючих проти мене бісів і в смертній небезпеці допомагай мені, щодня являючи мене непереможним для видимих і невидимих ворогів, щоб знали всі вони, що я — Твій раб, Богоматір, що народила Бога і Царя всіх, Якому належить честь і поклоніння на віки віків. Амінь."]},{"h":"Година п’ята","ps":["Діво Владичице, Мати Господа мого Ісуса Христа, знаю я, що не чистий, осквернений, недостойний, беззаконня мої перевищили міру, стали незліченніші за пісок морський.","До Тебе вдаюся, приносячи покаяння й сповідуючись у гріхах моїх. Прости мене, Владичице.","Помилуй мене, всіх милуюча чоловіколюбно!","Не відвертай лиця Свого від мене, щоб я, упокорений, не був відвернений від Тебе! Нехай не зрадіють цьому вороги мої.","Пробуди думку мою на покаяння й спрямуй мене на путь спасіння. Вступивши на нього, нехай маю Тебе супутницею, щоб Твоєю допомогою спастися.","Владичице, Мати Чоловіколюбного Бога! Упокор серце моє й виповни його скрухою; дай очам моїм сльози й просвіти їх світлом молитов Твоїх; окропи й очисти мене гісопом милосердя Твого; обмий мене за благодаттю Твоєю моїми слізьми.","О, Мати Господа мого Ісуса Христа, прийми смиренну сповідь і молитву мою; залишок життя мого збережи в покаянні; під час відходу душі моєї з тіла милостиво поглянь на мене, визволи від нещадних мучителів, будь моєю захисницею й знищ рукописання гріхів моїх.","Спасеним приведи мене до престолу Сина Твого, і Безначального Отця Його, і Всесвятого Духа, — світлоначальній і єдиносущній Тройці, Якій належить усяка слава, честь і поклоніння на віки віків. Амінь."]},{"h":"Година шоста","ps":["Діво, Владичице, Пречиста Богородице, всеславна Пані моя, вища за небеса, чистіша за промені сонячні, чесніша за херувимів, славніша за небесні воїнства, похвало апостолів, проповіднику мучеників, радосте преподобних, сяйво подвижників, золота кадильнице, світлоносний світильнику, істинний ковчегу, найбожественніший законе, незгораюча купино, розцвіла жезле Аронів! Ти воістину стала жезлом, а Син Твій Христос, Бог і Творець мій, є істинний Цвіт. Ти по плоті народила Бога Слово, і до народження, і по народженні Ти залишилася Дівою. Тобою примирилися ми з Богом Отцем через Христа, Сина Твого.","Ти — помічнице грішних і безпомічних, втіхо світові, захисте сиріт, викуплення з полону, опоро чернецтва, надіє мирян.","Ти — терпіння, захист і покров удовам, похвала, радість і вінець дів. Чесна Владичице і Пані, прикрий і збережи мене, щоб не возвеличувався лукавий ворог мій наді мною.","Ти, Пренепорочна, — допомога моя, і не знаю, крім Тебе, іншого прибіжища. Зі слізьми благаю Тебе, Владичице, щоб Син Твій і Творець мій не засудив мене на вічні муки за безліч звершених мною гріхів. Благаю Тебе, щоб за Твоїм заступництвом увійти мені до обителі святих, де немає ні сліз, ні скорбот, ні смерті, ні муки, але де безперервна радість, насолода праведних, безконечне життя, втіха і слава!","Наповни вуста мої благодаттю Твоєю, спонукай язик мій славословити Тебе з радісною душею та гарячим серцем; дай мені силу проголосити ту ангельську пісню, яку промовив Тобі Гавриїл.","Удостой, Діво, смиренного раба Твого, звільнитися від пристрастей і гріхів. Розвій помисли, що приходять від диявола і насилаються для того, щоб скинути душу мою в пекло.","Дай мені, Діво, страх Божий і любов; дай мені життя непорочне, любов до Господа й ближніх, терпіння, смирення, стриманість і піст, сльози скрухи, думку про вічні муки і відразу до злих діл, щоб удостоїтися увійти в чертог Сина Твого і Бога і там з усіма святими прославити величне ім’я Пресвятої Тройці на віки віків. Амінь."]},{"h":"Година сьома","ps":["Діво Владичице Богородице, спільне спасіння християнського роду! Як мати, Ти невпинно дбаєш про нас; будучи жалісливою, Ти оточуєш нас Своїми благодіяннями, спасаючи, охороняючи, визволяючи від небезпек, оберігаючи від спокус, звільняючи від гріхів.","За все це дякуємо Тобі і, не приховуючи благодіянь Твоїх, оспівуємо дивні діла Твої, прославляємо співчуття, величаємо промисел, славословимо заступництво і, згадуючи, від яких небезпек визволилися ми при Твоєму заступництві, приносимо Тобі подячну пісню, що не може достойно відповісти великим благодіянням Твоїм.","Благаємо Тебе змилуватися над служителями Твоїми і за нас принести молитву Народженому Тобою Богові нашому, щоб визволив Він нас від вічних мук.","Всесвята Владичице Богородице! Ти бачиш, якими бідами оточує нас лукавий демон. Він навіює нам бажання віддаватися пристрастям. Не відверни лиця Свого від нас! Розірви тенета лукавого, знищ ворогів наших, припини заступництвом Своїм гнів Божий.","До благодіянь Твоїх приєднай і це моління наше, — і ми прославимо всесвяте ім’я Сина Твого і Бога нашого, з Безначальним Його Отцем і Животворящим Його Духом, нині і повсякчас, і на віки віків. Амінь."]},{"h":"Година восьма","ps":["Владичице, Богом дарована мені розрадо! Божественне зрошення внутрішньої спеки моєї, знову вирваний для очищення беззаконь моїх струмене в висохлому джерелі сліз моїх, променистий світильнику затьмареної душі моєї, керівництво шляху мого, прикриття наготи моєї, припинення стогонів моїх, полегшення бід, знищення кайданів! Вислухай благання мої і, розчулившись плачем моїм, змилуйся наді мною.","Схились на прохання моє, виконай невгамовне бажання моє, визволи мене від мучительної пристрасті, що день і ніч воює проти мене й убиває душу мою; визволи мене від стріл Веліара і від ворогів видимих і невидимих, заступництвом Твоїм удостой мене зрівнятися з преподобними і праведними, і зарахуй мене до рабів і служителів Твоїх у небесній оселі, в країні живих.","Благаю Тебе, спільне всіх заступництво, спільна всіх радосте, удостой мене звеселитися невимовною радістю Сина Твого і Царя в безконечному Царстві Його.","Дай мені увійти в чертог Його і там прославити Того, Кому належить усяка слава, честь і поклоніння нині і повсякчас, і на віки віків. Амінь."]},{"h":"Година дев’ята","ps":["Діво Владичице Богородице, Мати Христа Бога нашого! Мандрівникам супутничай і охороняй їх; полонених спасай від тяжкого рабства, втішай засмучених, полегшуй усяке тілесне страждання і звільняй від душевних недуг і пристрастей невидимими молитвами Твоїми, щоб, звершивши шлях у цьому тимчасовому житті, могли ми Тобою отримати вічні блага в Царстві Небесному.","Вірних правителів наших, що уповають на Твою милість і заступництво, зміцни проти оточуючих їх ворогів; розжени хмару печалі, що бентежить душі їхні, визволи від зневіри й ослаблення і подай їм світлий і радісний стан духа, дарувавши мир і спокій державі їхній. Спаси молитвами Твоїми, Владичице, присвячену Тобі паству, все місто й країну — від голоду, трусу, потопу, вогню, меча, навали іноплемінників і міжусобної брані; і праведний гнів Божий відверни від нас за благоволінням і благодаттю Єдинородного Сина і Бога Твого, Якому належить усяка слава, честь і поклоніння, з Безначальним Його Отцем, і Пресвятим, і Благим, і Животворящим Його Духом, нині і повсякчас, і на віки віків. Амінь."]},{"h":"Година десята","ps":["Діво, Владичице, благодатна Богородителько, Преблагословенна, Богоблагодатна, вмістилище Божества: Єдинородного Сина Безсмертного й невидимого Отця! Прихили вухо Твоє до мене і вислухай слова, що вимовляються моїми нечистими й поганими устами! Зі скрушеним серцем і смиренними помислами вдаюся до милосердя Твого.","Не залиш мене нещасного в зневазі, не допусти загинути мені, недостойному рабу Твоєму. Зціли окаянну душу мою, охоплену лукавими пристрастями.","Ворог потоптав її, скрушивши гріхами розпусти… Гірко й соромно мені, і не смію просити в чоловіколюбного Бога мого прощення за безліч гріхів і зцілення невиліковних виразок моїх.","Осквернив я храм тілесний, непристойними бажаннями осквернив його і недопустимими вчинками образив усі почуття мої…","Тому не смію здіймати до Нього руки, забруднені лихими ділами. І на молитву розкрив я вуста мої, осквернені лихослів’ям і наклепом на ближнього. Тому перед Твоїми щедротами повергаюся в прах, нещасний і заблудлий.","Немає в мене іншої надії, немає іншого прибіжища, крім Тебе, єдина моя втіхо, радосте душі моєї, визволення від скорботи, викуплення з полону, обожнення смертних, відродження падших, відновлення душі моєї й тіла, променистий світильнику затьмареної душі моєї, прикриття наготи моєї, припинення ридань моїх, зміно долі моєї!..","На Тебе вся надія: не позбав нас заступництва Твого, але допомагай і покровительствуй нам! Приємні прохання Твої Синові Твоєму, бо Той, Хто благоволив прийняти на Себе вигляд раба, зберігає милість Свою до Тебе, що послужила Йому невимовним народженням.","Він радіє заступництву Твоєму і, вважаючи славу Твою за Свою власну, охоче виконує їх.","Не залиш мене нещасного в зневазі, Богородице, і неблаговидність вчинків моїх нехай не послужить до припинення милості Твоєї.","Допомоги міцнішої за Твою не бачу ніде, і винний у багатьох прогрішеннях, з розкаянням вдаюся до Тебе, скорої помічнице в потребах, і з глибини серця вигукую: помилуй мене, сповненого лінощів і безтурботності, прийми моє нікчемне моління і молитвами Твоїми яви мене приємним Синові Твоєму і Богові, і Царства Небесного удостой мене бути учасником, славословлячи в Тройці Єдиного Бога нині і повсякчас, і на віки віків. Амінь."]},{"h":"Година одинадцята","ps":["Владичице, Ти знаєш, що немає в мене надії на спасіння, бо добровільно розтлив душу й тіло своє, з юного віку став непотрібною й нікчемною посудиною; у всьому, окаянний, слідував я Веліару: і в помислах, і у вчинках своїх. Ще досі гнітить він волю мою, щодня будує мені підступи…","Навичку до гріха придбав я, і тільки часом приходить мені думка схаменутися…","Від усього серця даю страшну клятву Синові й Богові Твоєму, взиваючи: «Прости мені, Владико, гріхи мої! Відтепер перестаю грішити перед Тобою!»","Велике довготерпіння Твоє, Христе Життєдавче!","Як терпить Син Твій, Владичице, бачачи постійні клятвопорушення і брехню, яким немає міри в мені, окаянному!","Яка в мені безстрашність, яке зневажання! Ледве даю обіцянку, як уже відрікаюся від неї; до гіршого й більшого гріха прагну і ніколи не схаменуся…","Благаю, Пречиста Владичице! Допоможи мені! Не допусти мені стати здобиччю лукавого.","Вчини мене рабом Сина Твого і достойною посудиною Всесвятого Духа!","Спаси мене, Всеспівана, як Сама Ти хочеш і знаєш; дай мені лише прославити Тебе всією душею і від усього серця взиваючи до Тебе:","Радуйся, пісне херувимська, співе ангелів!","Радуйся, мире й радосте людей!","Радуйся, раю насолод!","Радуйся, дерево життя!","Радуйся, стіно вірних, пристанищо тих, що в біді!","Радуйся, Адамове покликання!","Радуйся, Євине викуплення!","Радуйся, джерело благодаті й безсмертя!","Радуйся, запечатана посудино Святого Духа!","Радуйся, найбожественніший храме!","Радуйся, престоле Господній!","Радуйся, Непорочна, що скрушила голову змія!","Радуйся, прибіжище виснажених працею!","Радуйся, викуплення від прокляття!","Радуйся, що в Народженому Тобою явила радість світові!","Радуйся, Мати Христа, Сина Бога Живого, Якому належить слава, честь і поклоніння нині і повсякчас, і на віки віків! Амінь."]},{"h":"Година дванадцята","ps":["Рід людський у Тобі, Богородице, придбав собі Заступницю перед Народженим Тобою Богом, від Твого залежить заступництва і в Тобі має захист, бо Ти маєш сміливість до Сина.","Тому й я до Тебе вдаюся з палким серцем і, не сміючи приступити до Сина Твого, Тебе благаю про спасіння: щоб побачив я Його за Твоїм заступництвом!..","Почуй раба Твого, що всю надію свою після Бога на Тебе покладає, і помилуй служителя Твого, Мати Чоловіколюбного й Милосердного Бога!","Визволи мене від осудженої совісті: погаси жар розпусти й запали в мені любов до Сина Твого і Бога; огородь мої почуття від непристойних бажань.","Благаю Тебе: нехай буде мені даний строк для покаяння, щоб не вразила мене смерть безплідного, щоб я, як безплідний, не був преданий вогню.","Запали погаслий світильник душі моєї, розжени мороку скорбот моїх, туман пристрастей віджени молитвами Твоїми.","Дай мені світло покаяння, спрямуй до скрухи, удостой мене всі дні життя мого догоджати Чоловіколюбцю Богові!","Доки перебуваю в цьому житті, покровительствуй мені й охороняй мене: з мандруючим мною мандруй, з подорожуючим супроводжуй у блуканнях, сплячого покривай і всі шляхи мої роби легкими.","Коли ж душа моя виходитиме з тіла, стань при мені, Владичице, вгамуй мою біль, полегши мої страждання, а бідній душі моїй вкажи путь у вічні обителі…","Нехай не зустрінуть мене темні сили і не затягнуть на дно пекла! Нехай побачу Суддю милостивим; нехай Тобою, Богоневісто, визволюся від вічного полум’я, насолоджуся райською втіхою в Тройці й отримаю Небесне Царство!","Охоронюваний Тобою, возвеличу й прославлю Тебе, бо Ти стала захистом людського роду. Всі народи ублажають Тебе, Діво Владичице Богородице, надіє всіх християн.","Від мене, смиренного раба Твого, прожени: зневіру, забуття, незнання, нерадіння, марнославство, перелюб, блуд, ненажерливість, усі лукаві помисли окаянного серця мого і затьмареного розуму мого.","Визволи мене від усіх лихих прагнень моїх, бо я немічний, а Ти — препрославлена перед усіма смертними, як Мати Христа Бога нашого, Якому належить усяка слава, честь і поклоніння на віки віків. Амінь."]},{"h":"Година тринадцята","ps":["Пресвята Владичице Богородице, радосте пригноблених, заступнице скривджених, помічнице безпомічних, сило немічних, жезле сліпих, спасительний вожде заблудлих, святий ковчегу, яким ми спаслися від гріховного потопу; незгораюча купино, що її бачив Богобачач Мойсей, золота кадильнице, з якої Слово, запаливши плоть, наповнило всесвіт пахощами; Богописана скрижалю, семисвічний світильнику, блиск якого перевершив сяйво сонця; свята скинії, яку збудував духовний Веселіїл; посудино, що вмістила в собі манну; джерело запечатане, чисті струмені якого напувають всесвіт; розцвіла жезле Аронів, росоносне руно Гедеона; Богописана книго, ради якої розірвано рукописання Адамове; горо Божа, на якій благоволив жити Господь; святий корене Єссеїв; граде Божий, про якого славне говорилося (Пс. 86, 2); прекрасна за природою, недоступна докорам; що вмістила в собі всю суть Божества; дарунку безцінний; прикрасо дорожча за всі краси; Єзекіїлеві врата, що дивляться на схід (Єз. 40, 6); розпечені кліщі, які бачив Ісая (Іс. 6, 6); нерубана горо Даниїлова (Дан. 2, 34); горо, оповита доброчесностями (Авв. 3, 3); прикрашене житло Божого сходження, примирення світу, раю найсвятіший, насаджений у Едемі; животворяче дерево, пахуча розо, незів’яний цвіте, найбіліша лілеє; образе дівства, накреслений без літер; Боготкана порфіро, найяснійше виконання кожного пророцтва, невпинні уста апостолів, певність непереможних переможців, утвердження царів, похвало священиків, прощення прогрішень, умилостивлення праведного Судді, відновлення душі моєї й тіла; спасіння моє, втіхо моя, життя моє, світло моє, надіє моя, розрадо моя, прибіжище моє; покрове, сило, веселощі, солодосте, стіно, огорожа, зброє, захисте, славо, тишо, мире, пісне, радосте, благословення, якорю, достатку, росо, святине; визволення від печалей, просвітлення й освячення душі моєї, викуплення гріхів моїх, упокоєння моє в Бозі; стриманосте, непорочносте, мужносте, цнотливосте, свободо, пристанищо, скарбе, висото, міцносте, красо, розсудливосте; вічне надбання, утвердження в покаянні, невсипуще моє перед Богом заступництво!.. Ти бачиш віру мою і захоплену любов, і, будучи співчутливою та могутньою, як Мати Милосердного Бога, прийми нещаснішу душу мою.","Заступництвом Своїм удостой її бути праворуч Сина Твого і Бога й упокоїтися з обраними й святими Його.","Не позбав мене заступництва Твого, бо боржником Своїм маєш Його, Який сказав: шануй батька твого і матір твою (Мф. 19, 19).","Всю надію мою покладаю на Тебе, бо Ти народила в плоті істинного Бога, Якому належить усяка слава, честь і поклоніння, з Безначальним Його Отцем, і Пресвятим, і Благим, і Животворящим Його Духом, нині і повсякчас, і на віки віків. Амінь."]},{"h":"Година чотирнадцята","ps":["Мати Божа, Ти — вища за всяке розуміння! О Діво, що перевершила всяке дівство, бо до народження Воплощеного Ти була Дівою понад усіх дів, і такою ж залишилася в самому різдві й по різдві!","О Діво, Якою людська природа, що колись відступила від Бога, за законом невимовного чоловіколюбства з’єдналася з природою Божества так, що іпостась не зазнала ні злиття, ні зміни!","О Діво, Якою після примирення ми, через заздрість лукавого не виконуючи свого обов’язку, знаходимо милостивим до себе Сина Твого і Бога.","Тебе, Владичице, прошу, Тебе благаю, милосердна й чоловіколюбна Мати милосердного й чоловіколюбного Бога: і в цю годину захисти мене, що потребую Твого покрову.","Я — житло всіх згубних для душі пристрастей. Мучуся страхом від незліченної безлічі гріхів моїх.","Яке із почуттів своїх не осквернив я, окаянний? Якими марними помислами не розтлив я душі своєї? Чим тільки не полонявся розум мій?","Пристрасний, слабкий, негідний розум мій, діючи заодно з винуватцем зла, одягає в образи й надає відтінок дійсності тому, чого ніколи не бачив і не чув я насправді.","Не відкинь, Владичице, упокореного благання мого, будь моєю визволителькою, щоб, спасений благодаттю Твоєю, я прославляв Тебе й славослов’ям Всеблагу Тройцю на віки віків. Амінь."]},{"h":"Година п’ятнадцята","ps":["Владичице, Мати Благого, Всеблагого і Преблагого Бога, на молитви непотрібного раба Твого поглянь милостиво і вчини зі мною за невимовним милосердям Твоїм, залишивши без уваги прогрішення мої, звершені в слові чи ділі, з моєї волі чи проти волі, свідомо й несвідомо. Онови всього мене, зробивши храмом Всесвятого і Животворящого Духа, Який є сила Вишнього, Який осінив пречисте лоно Твоє і жив у ньому.","Ти — помічнице виснажених працею, заступнице тих, що в біді, спасителько тих, що в бурі, пристанищо тих, що в хвилюванні, захиснице застигнутих нуждою.","Даруй же рабу Твоєму скруху серцеву, спокій думок, цнотливість розуму, душевну бадьорість, смирення в образі думок, благочестивий настрій духа, розсудливу вдачу, а також мир, який Господь наш дарував учням Своїм.","Нехай досягне моління моє святого храму Твого і в оселі слави Твоєї нехай піднесеться. Нехай із очей моїх проллються джерела сліз, і Ти омиєш мене моїми власними слізьми, очищаючи ними від пристрастей.","Заглади рукописання гріхів моїх, розжени хмару печалі моєї, мряку й сум’яття дум, усунь від мене хвилювання пристрастей, збережи мене в тиші, нічим не порушуваній, звесели мене невимовною розрадою й безперервним радіснням, щоб, ідучи правим шляхом заповідей Сина Твого, без докорів совісті пройти мені поприще життя.","Даруй мені, що молюся нині Тобі, чисту молитву, щоб день і ніч безтурботним розумом і неблукаючим розмірковуванням я навчався словам Божественного Писання: сповідуючи, оспівував і в радості серця приносив молитву на честь і славу Сина Твого і Господа нашого Ісуса Христа, Якому належить усяка слава, честь і поклоніння нині і повсякчас, і на віки віків. Амінь."]},{"h":"Година шістнадцята","ps":["Милостива Мати чоловіколюбного й милостивого Бога, почуй мене з висоти слави Твоєї, удостой слуху Твого слова мої, вислухай волання моє, що виходить із глибини душі, і скорботного моління мого не відкинь!","Ти, що даруєш мені життя заступництвом Своїм, дозволь мені відкрити вуста мої, щоб сповістити велич Твою перед кончиною моєю.","Згрішив я, Всенепорочна, згрішив, і беззаконня мої я знаю, і гріх мій передо мною є повсякчас (Пс. 50, 5).","Зійди до останнього благання мого і до сповіді раба Твого; дай мені потоки скорботних сліз і очисти ними багно гріхів моїх; у скам’янілому серці моєму оселі святий страх Сина Твого і Бога; проникни в нутро моє, щоб очистився я слізьми і відродився в мені спасительний дух.","Розумне світло запали в затьмареному розумі моєму, щоб у тиші й чистоті світла цього я поніс жертву, яку заповів Син Твій і Бог мій, Який прийшов закликати до покаяння грішників, а не праведників, і Який за заступництвом Твоїм прийме і мене недостойного.","Багато було таких, що згрішили від віку, Владичице; багато було в усі часи тих, що не дотримувалися заповідей Сина Твого; але немає жодного, хто б перевершив мене кількістю беззаконь.","Увесь Старий і Новий Заповіт славить доброчесності праведників; але внутрішній суд совісті моєї показує мені, що гріхи й беззаконня мої перевищують усе лихе від віку.","Адам отримав заповідь і закон, але не дотримав їх. Але він, Пречиста, ще не зазнав на досвіді іншого падіння й осуду. А я, нещасний, що можу сказати на своє виправдання? Будучи нестриманим і своєвільним, я прагнув стати лихим; тому немає мені вибачення, нещаснішому за всіх нещасних нащадків Адама, нещаснішому за содомлян, поглинутих вогнем.","Так усвідомлюю, що я нещасніший за всіх нещасних і грішніший за всіх грішних Нового Заповіту; охрестившись, осквернююся; будучи удостоєний прийняття благодаті, зодягаюся в ганьбу гріхів і знищую благодать, отриману при хрещенні. Чи вистачить у мене думки й слів, часу й засобів для очищення гріхів моїх, які великі, як море? Що буде зі мною? Яким шляхом іти мені? Небесний шлях недоступний, земний тісний, підземний страшний, морський загороджений. У невимовній скруті перебуваю я, неминуча небезпека повсюди підстерігає мене, думка і слово висихають. Могутня Мати Всемогутнього і Живого Бога, подай руку допомоги мені, позбавленому допомоги, і підніми душу мою, сказавши їй: «Я — твоє спасіння!» Вислухай благання моє і вирви мене з безодні лих, і прославлю Тебе, Преблагословенна Мати Христа Бога нашого, Якому належить слава, честь і поклоніння на віки віків. Амінь."]},{"h":"Година сімнадцята","ps":["Діво, Владичице, Богородице, що народила Творця і Владику всього видимого й невидимого, Єдиного з Тройці, Бога і людину: що стала обителлю Божества, вмістилищем святині й благодаті, в якій за благоволінням Бога Отця і при співдії Святого Духа тілесно жила повнота Божества; що маєш перевагу перед усяким створінням, славо і втіхо, і веселощі ангелів, царський вінче апостолів і пророків, надприродна мужносте мучеників, честе і славо преподобних, оборонице в подвигах і подателько перемог, непомильна путівнице, наставнице мовчання, двері одкровень і духовних таємниць, джерело світла, брамо вічного життя, невичерпна ріко милосердя, невичерпне море дарів і чудес.","Благаємо Тебе, співчутлива Мати чоловіколюбного Владики, будь милостива до нас, смиренних і недостойних рабів Твоїх, схились на смирення наше, розжени видимих і невидимих ворогів.","Будь перед лицем ворогів наших для нас, недостойних, бойовою зброєю, міцною охороною і непереможною оборонницею, щоб пізнали беззаконні, що Тобі все можливе, що Ти захочеш, Владичице, звершити на небі чи на землі, бо Ти воістину Богородиця, що народила в плоті істинного Бога, єдиного Царя і Владику всіх, Якому належить усяка слава, честь і поклоніння на віки віків. Амінь."]},{"h":"Година вісімнадцята","ps":["Діво Владичице Богородице, зі слізним благанням вдаюся я до Тебе нині. Випроси в Сина Твого і Бога залишення попередніх моїх прогрішень; виконай, Пренепорочна, благання моє і вкажи мені спосіб, за якого я міг би залишок життя свого, подібно до останніх годин цього згасаючого дня, провести в покаянні, смиренні й чистоті.","Преблагословенна Владичице, не відкинь смиренного прохання мого, але і в цьому житті, і при відході окаянної душі моєї, і на майбутньому страшному й непідкупному суді з’явись моєю оборонницею і спасителькою, щоб, осяяний променями Твоїми, прославляв я Тебе і невпинно славословив піснеспівами Всеблагу і Блаженну Тройцю на віки віків. Амінь."]},{"h":"Година дев’ятнадцята","ps":["Діво Владичице Богородице, що носила в утробі Христа Спасителя і Бога нашого, на Тебе покладаю всю надію, на Тебе уповаю, бо Ти — вища за безплотні сили!","Збережи мене, Пречиста, Своєю Божественною благодаттю; керуй життям моїм згідно зі святою волею Сина Твого і Бога нашого.","Даруй мені відпущення гріхів і будь мені прибіжищем, покровом, захистом і путівницею в життя вічне!","У страшну годину смертну не залиш мене, Владичице, але поспіши на допомогу мені і вирви мене з рук бісів-мучителів. Ти маєш силу виконати це, будучи істинною Матір’ю Божою.","Прийми ж єдиної Тобі гідні дари від нас, смиренних рабів Твоїх, Всесвята Владичице Богоматері, обрана від усіх родів і виявлена вищою за всі створіння земні й небесні!","Тобою ми пізнали Сина Божого; Тобою з’явився посеред нас Господь сил, і удостоїлися ми святого Тіла і Крові Його…","Блаженна Ти в роди родів, Богоблаженна, святіша за херувимів і славніша без порівняння за серафимів! І нині, Всесвята, не перестань молити за нас, недостойних рабів Твоїх, щоб визволилися від підступів лукавого і уникли крайніх і безвихідних обставин.","Молитвами Своїми збережи нас неосудженими, щоб, спасені Твоїм заступництвом і Твоєю допомогою, ми возсилали хвалу подяки й поклоніння Єдиному в Тройці Богові і Створителю всіх нині і повсякчас, і на віки віків. Амінь."]},{"h":"Година двадцята","ps":["Пресвята Владичице Богородице, Благодатна Богородителько, Преблагословенна, Богоблагодатна Богомати, вмістилище Божества: Єдинородного Сина Безсмертного й невидимого Отця, вогнеподібний престоле, Всенепорочна, Всепречиста, Всеспівана, Найблаженніша, Всенеторканна, Всечесна, Всешанована, Всеблагословенна, Всебажана Діво душею, розумом і тілом; троне Царя, що сидить на херувимах; небесна брамо, якою ми входимо на небо; Богоневісто, Якою прийшло до нас примирення з Богом; незбагненне чудо, незрозуміла вісто, відкриття потаємної Божої таємниці, неподолане заступництво, могутній захисте, животворче джерело, невичерпне море божественних дарів; висото, що перевершуєш небесні сили; недоступна дослідженню глибино потаємних думок; після Тройці спільна всіх Владичице, після Утішителя спільна всіх Утішительнице, після Посередника спільна Заступнице за весь світ; колесницю мисленого Сонця — істинного Світла, Що просвічує кожну людину, яка приходить у світ (Ін. 1, 9); що носиш Того, Хто все носить словом Своїм; одежо Того, Хто зодягається у світло, як у ризу; мосту всесвіту, що виводиш нас до понадсвітового неба; без порівняння вища й славніша за херувимів і серафимів; прикрасо ангелів, спасіння людей; Мати і рабо Незахідної Зорі; променю істинного дня; безодне невимовного чоловіколюбства Божого; тверда опоро правої віри; істинна виноградна лозо, що принесла плід життя; блискавко, що осяюєш душі; безпеко тих, що перебувають на висоті; плодоносна маслино, що радуєш вірних; відродження падших, збудження лінивих, міцносте пильних, єдинодумство Церков, непереможносте військ, благоустрою міст, мире всесвіту, твердосте подвижників, мужносте мучеників; хмаро, що точиш небесну росу!","Немає в мене допомоги й захисту, крім Тебе. На Тебе надіючись, нехай не залишуся я без очікуваного.","Тобою хвалюся: за безліччю беззаконь моїх не відверни лиця Твого від мене, недостойного раба Твого.","Є в Тебе могутність, як у тієї, що невимовно народила Єдиного з Тройці. Є в Тебе чим переконати й чим вмилостивити! Є руки, на яких Ти носила Його; є груди, якими Ти годувала Його немовлям.","До того, що від Тебе, приєднай і те, що від Нього: хрест, кров і рани, якими ми спасені й прославлені. Він завжди звершить угодне Тобі, що послужила Йому народженням у справі викуплення.","Ти наповнила світ благодіяннями.","Ти віднімаєш усяку сльозу з лиця землі.","Ти звеселила небесних і спасла земних.","Ти вмилостивила Творця, схилила ангелів, піднесла людство.","Ти примирила між собою горішніх і дольних.","Ти все змінила на краще, все перетворила на досконаліше.","У Тобі ми маємо непомильну ознаку нашого воскресіння, Тобою надіємося досягти Небесного Царства, у Тобі придбали ми помічницю нашого спасіння!","Богородице! Ти відкрила нам доступ у рай і полегшила нам сходження на небо. Ти зробила нас своїми Синові й Богові Твоєму.","Тобою, Пречиста, від Адама і до скінчення віку була, є і буде слава й честь апостолам, пророкам, мученикам, праведникам, і про Тебе, Благодатна, радіє вся тварина, про Тебе благословляючи Єдиного в Тройці Бога на віки віків. Амінь."]},{"h":"Година двадцять перша","ps":["Пречиста Богородице, заступнице моя, прийми молитву недостойного раба Твого.","Вірую, Всенепорочна, що можеш виконати це й спасти мене.","Надія моя, Владичице, на мені, що нещасніший за всіх, яви тим більше дивні милості Твої.","Ти знаєш думки й вчинки мої, Тобі не безвідома немічність моя.","Тобі довіряю душу мою, осквернену гріхами.","Ти бачиш, Владичице, виразки мої: зціли ж їх, влививши краплю співчуття Твого.","Твоє заступництво за зневірену душу прихильно приймає Той, Хто поставив Тебе прибіжищем грішників, Син Твій і Цар усіх, Якому належить усяка слава, честь і поклоніння з безначальним Його Отцем, і Пресвятим, і Благим, і Животворящим Його Духом, нині і повсякчас, і на віки віків. Амінь."]},{"h":"Година двадцять друга","ps":["Пресвята Владичице Богородице, почуй жалібне благання це і виконай його в міру надії моєї на надію всіх кінців землі.","Погаси жар у тілі моєму, угамуй бурю гніву, знищ до кінця зарозумілість марнославної юності.","Зменши в серці моєму лукаві мрії, уночі насилані лукавим духом; послаб щоденний приплив нечистих помислів.","Навчи язик мій говорити лише про корисне, а очі мої бачити красу доброчесності.","Очисти вуста мої, щоб сміливо міг я називати отцем Всевишнього Бога.","Відкрий вуха мої, щоб міг я живитися слів Святого Письма, солодших за мед, і виконувати їх Твоєю допомогою.","Дай мені строк на покаяння і визволи мене від раптової кончини.","Стань при мені при розлученні смиренної душі з бідним моїм тілом; послаб тоді нестерпні муки, полегши невимовну тугу, утіш у безрадісному становищі, визволи від споглядання бісів, звільни від безжальних мук повітряних митарів, відбий полум’яні мечі гріхів моїх, удостой на страшному суді стати праворуч Сина Твого, спаси від нескінченних мук і даруй успадкувати вічне блаженство.","Тобі, Владичице Богородице, світло затьмарених очей моїх, втіхо душі моєї, надіє моя і спасіння моє, приношу цю сповідь!","Очисти мене від усякої скверни плоті й духа, удостой мене в теперішньому житті неосудно причащатися пречистої Крові й Тіла Сина і Бога Твого, а в майбутньому віці удостоїтися причастя солодощів небесної вечері, райських насолод, Царства Божого.","Удостоївшись отримання цих благ, буду повіки славити Сина і Бога Твого, з Безначальним Його Отцем, і Благим, і Животворящим Його Духом, нині і повсякчас, і на віки віків. Амінь."]},{"h":"Година двадцять третя","ps":["Всеспівана Владичице, джерело милосердя, безодне чоловіколюбства, водо жива, заступнице грішних, істинна виноградна лозо, небесне блаженство, спільне всіх прибіжище, життя всього світу!","Віддавшись світові бунтівному й перелюбному, безтурботний я в помислах і вчинках і марно проводжу життя своє.","Але Ти, співчутлива Мати Божа, не погордуй мною грішним. Прийми моління моє, приношуване Тобі оскверненими устами моїми, і Твоїми прихильними молитвами милостивим до мене яви Суддю.","Випроси в Сина Твого, щоб не зважав на гріхи мої; спрямуй думки мої на покаяння; не допусти мені стати здобиччю сатани. Заступництвом Твоїм онови мене й виправ життя моє, щоб безбоязно мені постати перед Суддею й уникнути страшної муки.","Учини мене спадкоємцем слави, благаючи про це Творця мого, Якому належить усяка слава, честь і поклоніння на віки віків. Амінь."]},{"h":"Година двадцять четверта","ps":["Дякую Тобі, Владичице Богородице, і славлю Тебе за те, що Ти дала мені можливість дожити до кінця дня і до цієї нічної пори, коли я випрошую Твоїх молитов!","Прости мене, Всенепорочна, за лінощі й безтурботність і наповни мене старанням, щоб невпинно приносити піснеспіви Тобі й Чоловіколюбному Синові і Богові Твоєму за те, що я, окаянний, визволявся і визволяюся від хвороб, напастей і скорбот душевних і тілесних.","Припадаючи до Тебе, з серцем вдячним і захопленим вигукую і возглашаю Тобі подячну пісню, раб Твій, помилуваний Тобою, Преблагословенна Мати Чоловіколюбного Бога:","Радуйся, Всенепорочна, благословенна!","Радуйся, Діво, славо людей!","Радуйся, виконання всіх пророцтв!","Радуйся, печатко завіту Господнього!","Радуйся, пояснення таємниць Господніх!","Радуйся, соборе тих, кого несправедливо позбавлено честі!","Радуйся, з’єднання давно розділених!","Радуйся, опоро тих, що схилилися долу!","Радуйся, просвітлення тих, що в темряві!","Радуйся, оновлення знівечених!","Радуйся, умилостивна жертво заблудлих!","Радуйся, путівний маяку тих, що блукають!","Радуйся, пристанище тих, що пливуть!","Радуйся, помічнице в потребах!","Радуйся, спасіння вірних!","Радуйся, новий Божественний даре!","Радуйся, Владичице всіх земнородних!","Радуйся, радосте й славо ангелів!","Радуйся, вища за всі створіння!","Радуйся, рабо Божа!","Радуйся, Благословенна повіки віків!","Радуйся, Маріє, Невісто-Матір!","Радуйся, прекрасна Доню Давидова!","Радуйся, трапезо таємничих дарів!","Радуйся, перемого Царя і Бога мого!","Радуйся, похвало патріархів!","Радуйся, стіно тих, що призивають Тебе!","Радуйся, тверда обороно й покрове!","Радуйся, престоле Самого Бога!","Радуйся, Мати Божа!","Радуйся, найсвятіше ложе Соломоново (Пісня над піснями, 3, 7).","Радуйся, розв’язання гріхів моїх!","Радуйся, багата помічнице бідним!","Радуйся, хранителько невичерпних щедрот!","Радуйся, Пречиста Мати і Діво!","Радуйся, Владичице Адамового роду!","Радуйся, мечу проти бісів лукавих!","Радуйся, всещедре дарування премудрості!","Радуйся, втіхо тих, що в біді!","Радуйся, причино всього прекрасного в житті!.."]}],"notes":[]},{"u":"Волання до Богородиці","e":"A Cry to the Mother of God","secs":[{"ps":["Про що благати Тебе, чого просити в Тебе? Ти ж усе бачиш, знаєш Сама, поглянь мені в душу й дай їй те, що їй потрібне. Ти, що все перетерпіла й подолала, — усе зрозумієш. Ти, що сповила Немовля в яслах і прийняла Його Своїми руками з Хреста, Ти одна знаєш усю висоту радості, весь тягар горя. Ти, що отримала в усиновлення весь рід людський, поглянь і на мене з материнською турботою. З тенет гріха приведи мене до Свого Сина. Я бачу сльозу, що зросила Твій лик. Це наді мною Ти пролила її, і нехай змиє вона сліди моїх прогрішень. Ось я прийшов, я стою, я чекаю Твого відгуку, о Богоматір, о Всеспівана, о Владичице! Нічого не прошу, лише стою перед Тобою. Тільки серце моє, бідне людське серце, знемагаюче в тузі за правдою, кидаю до Пречистих ніг Твоїх, Владичице! Дай усім, хто кличе Тебе, досягти Тобою вічного дня і лицем до лиця поклонитися Тобі.","Єта моли́тва напи́сана Є. Поселяниним і взята́ із журнала “Український і́нок” за 1910 г., стр. 29."]}],"notes":[]}];
export default D;
